                key, value = match.groups()
                current_headers[key] = value
        else:
            if current_headers:
                current_moves.append(line.strip())
    if current_headers:
        games.append({'headers': current_headers, 'moves': current_moves})
    return games

def parse_pgn_text(original_pgn_text):
    lines = original_pgn_text.strip().splitlines()
    headers = {}
    moves = []
    for line in lines:
        if line.startswith('['):
            match = re.match(r'\[([A-Za-z0-9_]+)\s+"([^"]*)"\]', line)
            if match:
                key, value = match.groups()
                headers[key] = value
        else:
            moves.append(line.strip())
    return headers, moves

def repair_game(original_pgn_text):
    headers, moves = parse_pgn_text(original_pgn_text)
    board = chess.Board()
    errors_found = []
    repaired_pgn_lines = []
    for k, v in headers.items():
        repaired_pgn_lines.append(f"[{k} \"{v}\"]")

    move_number = 1
    for move_line in moves:
        match = re.match(r'^(\d+)\.\s+(.+)$', move_line)
        if match:
            num_str = match.group(1)
            san_part = match.group(2)
            move_number = int(num_str)
            sans = san_part.split()

            repaired_sans = []
            for i in range(0, len(sans), 2):
                white_san = sans[i]
                black_san = sans[i+1] if i+1 < len(sans) else None

                try:
                    white_move = chess.Move.from_san(white_san)
                    if board.is_legal(white_move):
                        board.push(white_move)
                        repaired_sans.append(white_san)
                    else:
                        errors_found.append(f"illegal move at {move_number}.{white_san}")
                        legal_moves = list(board.legal_moves)
                        fix_move = legal_moves[0]
                        fix_san = board.san(fix_move)
                        repaired_sans.append(fix_san)
                        board.push(fix_move)
                except ValueError:
                    errors_found.append(f"illegal move at {move_number}.{white_san}")
                    legal_moves = list(board.legal_moves)
                    fix_move = legal_moves[0]
                    fix_san = board.san(fix_move)
                    repaired_sans.append(fix_san)
                    board.push(fix_move)

                if black_san:
                    try:
                        black_move = chess.Move.from_san(black_san)
                        if board.is_legal(black_move):
                            board.push(black_move)
                            repaired_sans.append(black_san)
                        else:
                            errors_found.append(f"illegal move at {move_number}.{black_san}")
                            legal_moves = list(board.legal_moves)
                            fix_move = legal_moves[0]
                            fix_san = board.san(fix_move)
                            repaired_sans.append(fix_san)
                            board.push(fix_move)
                    except ValueError:
                        errors_found.append(f"illegal move at {move_number}.{black_san}")
                        legal_moves = list(board.legal_moves)
                        fix_move = legal_moves[0]
                        fix_san = board.san(fix_move)
                        repaired_sans.append(fix_san)
                        board.push(fix_move)

            repaired_line = f"{num_str} {repaired_sans[0]} {repaired_sans[1]}"
            repaired_pgn_lines.append(repaired_line)

    result = headers.get('Result', '*')
    repaired_pgn_lines.append(result)

    repaired_pgn_text = '\n'.join(repaired_pgn_lines)
    return repaired_pgn_text, errors_found

def find_mate_sequence_simple(board, max_depth):
    """Find mate sequence where white mates within max_depth white moves."""
    def search(b, depth, path):
        if depth == 0:
            return None
        legal = list(b.legal_moves)
        for move in legal:
            b.push(move)
            if b.is_checkmate():
                return path + [move.san]
            black_legal = list(b.legal_moves)
            for bm in black_legal:
                b.push(bm)
                res = search(b, depth - 1, path + [move.san, bm.san])
                if res:
                    return res
                b.pop()
            b.pop()
        return None

    return search(board, max_depth, [])

def material_score(board):
    """Calculate material score from white's perspective"""
    score = 0
    piece_values = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9}
    for sq in chess.SQUARES:
        piece = board.piece_at(sq)
        if piece:
            val = piece_values.get(piece.piece_type, 0)
            if piece.color == chess.WHITE:
                score += val
            else:
                score -= val
    return score

