        best = legal[0]
        board.push(best)
        if board.is_checkmate():
            seq = [best.san]
            board.pop()
        else:
            seq = [best.san]
        return {
            "puzzle_id": puzzle_id,
            "best_move": best.san,
            "continuation": seq,
            "mate_in": 1
        }

    # Not mate problem - find best move
    legal = list(board.legal_moves)
